import re, pathlib
root=pathlib.Path('AlgebraicJacobian')
hits=[]
for p in sorted(root.rglob('*.lean')):
    txt=p.read_text()
    # strip block comments /- ... -/
    out=[]
    i=0; depth=0
    lines=txt.split('\n')
    for ln_no, ln in enumerate(lines,1):
        j=0; clean=''
        while j < len(ln):
            if depth==0 and ln.startswith('/-', j):
                depth+=1; j+=2
            elif depth>0 and ln.startswith('-/', j):
                depth-=1; j+=2
            elif depth>0:
                j+=1
            elif ln.startswith('--', j):
                break
            else:
                clean+=ln[j]; j+=1
        if re.search(r'\bsorry\b', clean):
            hits.append((str(p), ln_no, ln.strip()[:110]))
for h in hits:
    print(f"{h[0]}:{h[1]}: {h[2]}")
print("TOTAL", len(hits))
